const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

// 1. Captura os dados vindos dos nós anteriores
const clientes = $('Merge').item.json.body?.clientes || $('Merge').item.json.clientes || [];

// Busca a lista de investimentos tratada do nó "Code in JavaScript"
let investimentos = [];
try {
  investimentos = $('Code 1 - Ajustando informações do perfils').first().json.investimentos || [];
} catch (e) {
  investimentos = [];
}

// Funções auxiliares
function parseSaldo(saldoStr) {
  if (!saldoStr) return 0;
  return parseFloat(String(saldoStr).replace('R$', '').replace(/\./g, '').replace(',', '.').trim());
}

function pick(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return '';
  return arr[Math.floor(Math.random() * arr.length)];
}

// 2. Mapeia e cruza os dados dos clientes com os investimentos
const resultados = clientes.map((c) => {
  const nome = c.nome;
  const email = c.email;
  const perfil = c.perfil;
  const saldoNum = parseSaldo(c.saldo);

  // Procura a opção exata conforme o gabarito do professor
  const inv = investimentos.find((i) => {
    const p = (i.perfil || '').trim().toLowerCase();
    const prod = (i.produto || '').trim().toLowerCase();
    const perfCliente = (perfil || '').trim().toLowerCase();

    if (perfCliente === 'conservador') {
      return p === 'conservador' && prod.includes('cdb liquidez');
    }
    return p === perfCliente;
  }) || {};

  const recomendacao = {
    perfil: inv.perfil || perfil,
    produto: inv.produto || '',
    minimo: inv.minimo ? Number(inv.minimo) : 0,
    rentabilidade: inv.rentabilidade || ''
  };

  const motivo = 'saldo_ok';

  // Formatador de valor mínimo em moeda brasileira
  const minFormatado = recomendacao.minimo.toLocaleString('pt-BR', { minimumFractionDigits: 2 });

  // As 3 opções de frases idênticas às da aula
  const mensagens = [
    `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${recomendacao.produto}** (mínimo R$ ${minFormatado}). Com seu saldo atual (${c.saldo}), você já consegue investir. Rentabilidade: ${recomendacao.rentabilidade}.`,
    `Oi ${nome}! Recomendações para perfil ${perfil}: **${recomendacao.produto}** (mínimo R$ ${minFormatado}). Seu saldo (${c.saldo}) já atende o mínimo. Rentabilidade: ${recomendacao.rentabilidade}.`,
    `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${recomendacao.produto}** (mínimo R$ ${minFormatado}). Você tem ${c.saldo}, então dá pra aplicar. Rentabilidade: ${recomendacao.rentabilidade}.`
  ];

  return {
    nome,
    email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens),
  };
});

// 3. Estrutura final de saída do nó
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

