const code3Items = $items("Code 3 - Configurando mensagens em tabela");

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];

  // 1. Pega a resposta de texto gerada pela IA
  let responseText = item.json.content?.parts?.[0]?.text || item.json.text || "";

  // 2. Remove marcações Markdown
  responseText = responseText.replace(/```json/g, "").replace(/```/g, "").trim();

  // 3. Converte o JSON retornado pela IA
  let parsedEmail = {};
  try {
    parsedEmail = JSON.parse(responseText);
  } catch (e) {
    parsedEmail = {
      subject: "Oportunidade de Investimento",
      text_body: responseText,
      html_body: `<p>${responseText}</p>`
    };
  }

  // 4. Busca o email_to correspondente ao mesmo índice no Code 3
  const emailDestinatario = item.json.email_to || item.json.email || code3Items[i]?.json?.email_to || "";

  // 5. Preenche e padroniza a saída
  item.json.email_to = emailDestinatario;
  item.json.subject = parsedEmail.subject || "";
  item.json.text_body = parsedEmail.text_body || "";
  item.json.html_body = parsedEmail.html_body || "";
}

return $input.all();
